INSERT INTO ifr_version_scheme (code, label, definition) VALUES ('SemVer', 'SemVer', 'Semantic Versioning 2.0.0: MAJOR.MINOR.PATCH with an optional pre-release; build metadata after a plus sign is not part of precedence.');
INSERT INTO ifr_version_scheme (code, label, definition) VALUES ('CommitDateEdition', 'commit-date edition', 'The UTC date of the commit the edition is made at, a hyphen and the first eight characters of that commit: YYYY.MM.DD-commit8; never the clock.');
INSERT INTO ifr_version_scheme (code, label, definition) VALUES ('SnapshotDate', 'snapshot date', 'The day a dataset was snapshotted, YYYY-MM-DD, with the SHA-256 of the snapshot kept beside it and a SemVer for the schema of the data.');
INSERT INTO ifr_version_scheme (code, label, definition) VALUES ('IntegerRevision', 'integer revision', 'A whole number from 1 that a controlled document''s revision carries, raised only with an approval record.');
INSERT INTO ifr_version_scheme (code, label, definition) VALUES ('NoVersion', 'no version', 'The scheme of a specification: it has no version, its requirement identifiers are never renumbered and its revision is the commit.');
INSERT INTO ifr_work_kind (code, label, definition) VALUES ('Software', 'software', 'A program or a service.');
INSERT INTO ifr_work_kind (code, label, definition) VALUES ('Library', 'library', 'Code another program imports.');
INSERT INTO ifr_work_kind (code, label, definition) VALUES ('CommandLineInterface', 'command-line interface', 'A command, its options and its output, which a script depends on.');
INSERT INTO ifr_work_kind (code, label, definition) VALUES ('Ontology', 'ontology', 'A published vocabulary: its terms are its interface.');
INSERT INTO ifr_work_kind (code, label, definition) VALUES ('Schema', 'schema', 'A published schema of data or of a message.');
INSERT INTO ifr_work_kind (code, label, definition) VALUES ('Prose', 'prose', 'A book, a manual or a paper: published text.');
INSERT INTO ifr_work_kind (code, label, definition) VALUES ('Data', 'data', 'A dataset: a snapshot with its digest, and a SemVer for its schema.');
INSERT INTO ifr_work_kind (code, label, definition) VALUES ('ControlledDocument', 'controlled document', 'A policy or a procedure under document control: an integer revision and an approval.');
INSERT INTO ifr_work_kind (code, label, definition) VALUES ('Specification', 'specification', 'A specification: it has no version.');
INSERT INTO ifr_impact (code, label, definition) VALUES ('Major', 'major', 'A change that breaks what a user of the work relied on.');
INSERT INTO ifr_impact (code, label, definition) VALUES ('Minor', 'minor', 'A change that adds and breaks nothing.');
INSERT INTO ifr_impact (code, label, definition) VALUES ('Patch', 'patch', 'A change that corrects and adds nothing.');
